// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    Caller a1;
    Caller a2;

    function setUp() public {
        c = new keepMyEther();
        a1 = new Caller(c);
        a2 = new Caller(c);
    }

    function testFuzz_property(uint256 amount, bool pickSecond) public {
        amount = bound(amount, 1, 1e30);
        Caller actor = pickSecond ? a2 : a1;

        // deposit via fallback
        vm.deal(address(actor), amount);
        actor.deposit(amount);

        // withdraw through an accepting counterparty so the low-level call succeeds
        actor.withdraw();

        // Rule: after a successful withdrawal the caller's balance is zero.
        assertTrue(c.balances(address(actor)) == 0, "balance not zeroed after withdraw");
    }
}

contract Caller {
    keepMyEther c;
    constructor(keepMyEther _c) { c = _c; }
    function deposit(uint256 amt) external payable {
        (bool ok, ) = address(c).call{value: amt}("");
        require(ok);
    }
    function withdraw() external {
        c.withdraw();
    }
    receive() external payable {}
}
